/**
 * @param {$T.def_skill | null} class_skill const struct def_skill *
 * @returns {Promise<void>}
 */
export async function skill_init(class_skill) {   // weapon.c:1738
    let obj = null, skill = 0;
    /* initialize skill array; by default, everything is restricted */
    for (skill = 0; skill < P.NUM_SKILLS; skill = skill + 1) {
        u.weapon_skills[skill].skill = P.ISRESTRICTED;
        u.weapon_skills[skill].max_skill = P.ISRESTRICTED;
        u.weapon_skills[skill].advance = 0;
    }
    /* Set skill for all weapons in inventory to be basic */
    for (obj = gi.invent; obj; obj = obj.nobj) {
        /* don't give skill just because of carried ammo, wait until
           we see the relevant launcher (prevents an archeologist's
           touchstone from inadvertently providing skill in sling) */
        if (is_ammo(obj)) {
            continue;
        }
        skill = weapon_type(obj);
        if (skill !== P.NONE) {
            u.weapon_skills[skill].skill = P.BASIC;
        }
    }
    /* set skills for magic */
    if (Role_if(PM.HEALER) || Role_if(PM.MONK)) {
        u.weapon_skills[P.HEALING_SPELL].skill = P.BASIC;
    } else if (Role_if(PM.CLERIC)) {
        u.weapon_skills[P.CLERIC_SPELL].skill = P.BASIC;
    } else if (Role_if(PM.WIZARD)) {
        u.weapon_skills[P.ATTACK_SPELL].skill = P.BASIC;
        u.weapon_skills[P.ENCHANTMENT_SPELL].skill = P.BASIC;
    }
    /* walk through array to set skill maximums */
    for (; class_skill.skill !== P.NONE; class_skill = $c.radd(class_skill, 1)) {
        const skmax = class_skill.skmax;
        skill = class_skill.skill;
        u.weapon_skills[skill].max_skill = $c.i16(skmax);
        if (u.weapon_skills[skill].skill === P.ISRESTRICTED) {   /* skill pre-set */
            u.weapon_skills[skill].skill = P.UNSKILLED;
        }
    }
    /* High potential fighters already know how to use their hands. */
    if (u.weapon_skills[P.BARE_HANDED_COMBAT].max_skill > P.EXPERT) {
        u.weapon_skills[P.BARE_HANDED_COMBAT].skill = P.BASIC;
    }
    /* Roles that start with a horse know how to ride it */
    if (gu.urole.petnum === PM.PONY) {
        u.weapon_skills[P.RIDING].skill = P.BASIC;
    }
    /*
     * Make sure we haven't missed setting the max on a skill
     * & set advance
     */
    for (skill = 0; skill < P.NUM_SKILLS; skill = skill + 1) {
        if (!P_RESTRICTED(skill)) {
            if (u.weapon_skills[skill].max_skill < u.weapon_skills[skill].skill) {
                await impossible($C`skill_init: curr > max: %s`, P_NAME(skill));
                u.weapon_skills[skill].max_skill = u.weapon_skills[skill].skill;
            }
            u.weapon_skills[skill].advance = $c.u16(Math.imul(Math.imul(u.weapon_skills[skill].skill - 1, u.weapon_skills[skill].skill - 1), 20));
        }
    }
    /* each role has a special spell; allow at least basic for its type
       (despite the function name, this works for spell skills too) */
    unrestrict_weapon_skill(spell_skilltype(gu.urole.spelspec));
    if (!u.uroleplay.pauper) {   /* paupers lack advanced access to books */
        await skill_based_spellbook_id();
    }
}
